const stopWords = new Set(['a', 'an', 'and', 'are', 'as', 'at', 'best', 'build', 'for', 'from', 'guide', 'how', 'in', 'into', 'make', 'of', 'on', 'or', 'the', 'to', 'using', 'with', 'without', 'woodworking', 'your'])

const sentence = (value) => value ? `${value.charAt(0).toUpperCase()}${value.slice(1).replace(/[.]+$/, '')}.` : ''
const subjectOf = (title) => title.replace(/^(build|make|how to|the beginner(?:'s|s)? guide to)\s+/i, '').replace(/[.]+$/, '')
const lowerSubject = (guide) => subjectOf(guide.title).toLowerCase()
const articleWords = (guide) => [guide.title, guide.dek, ...guide.sections.flatMap((section) => [section.heading, ...section.paragraphs, ...(section.bullets ?? [])])].join(' ')
const priceBand = (band = 1) => ({ 1: '$25–$75', 2: '$75–$200', 3: '$200–$600', 4: '$600+' })[band] ?? 'Varies'

const factRules = [
  { test: /estimate the real cost of a woodworking project/i, answer: 'Estimate a project from a finished cut list, then add waste, hardware, consumables, finishing materials, delivery, and a deliberate contingency instead of multiplying board feet by one lumber price.', facts: ['Price rough lumber from the board-foot total plus a waste allowance that reflects defects, grain matching, and the parts that must come from wide or long clear stock.', 'Price sheet goods by full sheets, not by the square footage left in the project, and include the offcut only when it has a planned future use.', 'Count hardware, glue, abrasives, finish, brushes, rags, blades or bits consumed, and delivery; small lines routinely change the total more than expected.', 'Record estimated and actual quantities after the build so the next estimate is based on shop history rather than memory.'] },
  { test: /hand tools? vs\. power tools?/i, answer: 'Start with the route that completes the next three projects in the space you have: hand tools trade speed for quiet control and a small footprint, while power tools trade money, noise, dust, and setup space for repeatability and stock-removal speed.', facts: ['A hand-tool path still needs a stable bench, workholding, sharpening, and time to learn edge control.', 'A power-tool path still needs layout tools, hand fitting, guards, stock support, extraction, and suitable electrical capacity.', 'Many small shops work best as hybrids: portable power tools prepare and size stock, while hand tools tune joints and surfaces.', 'Choose the first route from actual material dimensions and project frequency, not from an identity about being a hand-tool or power-tool woodworker.'] },
  { test: /dowels? vs\. biscuits? vs\. dominos?/i, answer: 'Use biscuits mainly for fast registration, dowels when a lower-cost jig can control two matching hole patterns, and Domino-style loose tenons when repeated mortises, multiple tenon sizes, and speed justify the much higher system cost.', facts: ['Every route depends on registering both parts from the same reference face and keeping the tool square to the edge.', 'A dry-fit should close by hand or ordinary clamp pressure; force can hide an offset hole or mortise until glue makes the error permanent.', 'Biscuits can help align broad panels, but the joint still depends on sound mating surfaces and the project load path.', 'Price cutters, jigs, tenons or plates, dust collection, setup blocks, and the time needed to verify repeatability—not just the base tool.'] },
  { test: /woodworking safety gear you need/i, answer: 'Buy eye protection, hearing protection, and dust control for the operations you will perform before buying convenience gear; add a face shield, task-specific respirator or cartridge, gloves, and protective clothing only when the identified hazard calls for them.', facts: ['Eye protection needs the applicable impact rating and side coverage; a face shield supplements rather than replaces primary eye protection.', 'Hearing protection must fit the wearer and be comfortable enough to remain in place for the whole exposure.', 'Source capture and ventilation come before relying on a respirator, and the filter or cartridge must match particles, vapors, or both.', 'Gloves can protect during handling and finishing but should not be worn where rotating machinery can catch them.'] },
  { test: /table saw dust collection.*overarm.*cabinet/i, answer: 'Collect table-saw dust both below the table and as close as practical to the blade above it; cabinet pickup handles the chip stream beneath the table, while an overarm guard captures material that escapes from the top of the cut.', facts: ['An enclosed cabinet cannot capture all dust thrown above the table, especially during through-cuts and edge trimming.', 'An overarm pickup works best when the hood stays close to the stock without hiding the cut or interfering with a safe guard.', 'The upper and lower branches need enough airflow together; simply splitting one undersized hose can weaken both pickups.', 'Seal cabinet leaks deliberately while preserving motor cooling, tilt travel, dust-free controls, and access required by the machine maker.'] },
  { test: /giant woodworking plan bundles/i, answer: 'A giant plan bundle is worthwhile only when complete sample plans prove coherent dimensions, authorship, revision history, safe construction details, and a real correction or refund process; title count by itself has almost no value.', facts: ['Open complete samples and reconcile the drawings, cut list, materials, and written sequence before paying.', 'Look for author names, revision dates, units, hardware specifications, safety notes, licensing terms, and a visible corrections process.', 'Search several titles and images for duplication or material copied from unrelated publishers.', 'One plan that fits the shop and has buildable dimensions is worth more than thousands of uncurated files that require redesign.'] },
  { test: /jigsaw blade guide/i, answer: 'Choose a jigsaw blade from the material, finished-face orientation, cut direction, and minimum curve radius: tooth geometry controls splintering while blade width and thickness control how tightly and how straight it can cut.', facts: ['A narrow blade turns a tighter radius; a wider, thicker blade resists wandering in a straight cut.', 'Standard up-cut blades usually leave their cleaner edge on the bottom, while reverse-tooth blades can protect the top face but may increase lift and vibration.', 'Use enough teeth in the material to cut smoothly without packing the gullets; excess teeth create heat while too few can snag thin stock.', 'Keep the base flat, support the offcut, use relief cuts in tight waste, and replace a bent or dull blade instead of steering harder.'] },
  { test: /dado stack buying guide/i, answer: 'Choose a dado set only after the saw manual confirms compatibility, maximum stack width, blade diameter, arbor capacity, throat plate, and brake-cartridge requirements; then judge chip quality and width adjustment in the sheet goods actually used.', facts: ['The outside cutters must face the correct direction and the chippers and shims must follow the set maker’s stack chart.', 'An 8-inch set offers more cutting depth but adds rotating mass; many furniture dados do not need that capacity and some saws specify a smaller set.', 'Nominal plywood rarely matches a nominal dado width, so a useful shim range or plywood-specific cutter combination saves test fitting.', 'Use a suitable throat plate and never allow teeth from adjacent cutters or chippers to touch when the arbor nut is tightened.'] },
  { test: /shop organization on a \$100 budget/i, answer: 'Spend a small organization budget only after measuring the tools, material flow, wall structure, and unused space; labels, repaired storage, scrap-built holders, and a few well-chosen bins usually outperform one large generic cabinet.', facts: ['Put frequently used tools where they can be returned with one hand and without moving another object.', 'Store heavy tools low, restrain tall or mobile storage, and keep every wall load connected to verified structure.', 'Use existing offcuts for cleats, dividers, trays, and holders before buying decorative matching containers.', 'Reserve money for the few standardized bins, hooks, labels, or drawer slides that solve measured gaps and remain replaceable.'] },
  { test: /moisture meter/i, answer: 'Use a moisture meter to compare boards, find unusual wet areas, and track acclimation; correct for species, thickness, temperature, measuring depth, and meter type, then interpret the reading against the project’s service environment.', facts: ['Pin meters read along the electrical path between probes and can help compare depth when insulated probes are used; they leave small holes.', 'Pinless meters scan without probe holes but need a flat contact area and can be influenced by stock thickness, density settings, and nearby material.', 'Take several readings across faces, ends, and suspect areas rather than treating one number as the whole board.', 'The useful target is moisture content reasonably equilibrated with the project’s service environment, not one universal percentage for every climate and season.'] },
  { test: /woodworking for absolute beginners/i, answer: 'A first weekend should teach control: inspect and mark stock from one reference, practice each cut in scrap, dry-fit before glue, and finish one small project without rushing into a room full of machines.', facts: ['Begin with a stable work surface, workholding, eye and hearing protection, and a way to manage dust before adding specialty tools.', 'A first project with fewer than about twelve parts makes it easier to see how layout, square cuts, pilot holes, and assembly order affect the result.', 'Read the current manual and keep guards installed; stop when the stock or offcut cannot be supported through the complete operation.', 'Record one correction after the project so the next build begins from evidence instead of repeating the same setup error.'] },
  { test: /woodworking in an apartment|one-car-garage woodshop|how much space|lay out a woodshop|plan a woodshop/i, answer: 'Plan a small shop around material travel and safe operating envelopes, not a wall of parked tools: draw where a full board or sheet enters, is broken down, machined, assembled, and stored before assigning floor space.', facts: ['Mark the full infeed, outfeed, operator, door, car, and emergency-exit zones for every machine at the same scale.', 'Put mobile tools on stable bases only when their cords, hoses, center of gravity, and locking method remain controlled in use.', 'In an apartment or shared building, hand tools, daytime scheduling, vibration isolation, source capture, and smaller stock reduce disturbance but do not override lease or building rules.', 'A folding surface or shared outfeed-and-assembly table saves space only when it can be deployed without blocking an exit or creating an unstable setup.'] },
  { test: /wood grain direction|knots, checks, and grain|frame-and-panel|breadboard ends|wood movement|end grain and predict|flat-sawn|rift-sawn|quarter-sawn/i, answer: 'Read grain as structure: follow fiber direction for cleaner cutting, place defects outside critical load paths, and allow solid wood to change width across the grain without being locked to a rigid cross-grain part.', facts: ['Rising grain ahead of a cutter or plane often tears; reverse direction or change the cutting method when the fibers dive beneath the surface.', 'Knots, checks, short grain, pith, and reaction wood change strength and movement and should be mapped before the cut list is nested.', 'Frame-and-panel and breadboard-end construction restrain flatness while allowing the wide panel to move across its grain.', 'Tangential movement is generally greater than radial movement; board orientation changes the shape of seasonal distortion but does not eliminate movement.'] },
  { test: /woodworking mistakes|practice woodworking with scrap|30-day woodworking practice/i, answer: 'Practice one variable at a time on labeled scrap: establish a baseline, change one setup or technique, inspect the result, and repeat the accepted method before carrying it into project stock.', facts: ['Use scrap that matches the project thickness and material when fit, tear-out, color, or cutter setup is being tested.', 'A practice piece should answer one question—square, depth, fit, surface, or finish—not become an unmeasured miniature project.', 'Keep the accepted sample beside the tool until repeated parts are complete, then mark the material, setup, and date.', 'The most expensive beginner mistakes usually come from skipping the dry fit, ignoring stock defects, measuring repeated parts independently, or changing several variables at once.'] },
  { test: /story stick|lay out angles|imperial vs\. metric|cumulative error|measuring tools for furniture/i, answer: 'Transfer critical dimensions from one verified reference or full-size story stick instead of rereading a tape for every part; direct comparison prevents rounding and cumulative layout error.', facts: ['Check a square by drawing a line, flipping the tool against the same reference edge, and comparing the second line.', 'A bevel gauge transfers an angle without requiring its numeric value; a full-size drawing can establish the angle when no reliable edge exists.', 'Use one unit system through a drawing and cut list unless every conversion is resolved before work begins.', 'Repeated parts should share a stop or story stick so one setup error is visible instead of hidden in many independent measurements.'] },
  { test: /scale a furniture photo|buildable design/i, answer: 'A photograph becomes buildable only after one trustworthy real-world dimension establishes scale and the hidden structure, joinery, clearances, and wood movement are redesigned rather than guessed from perspective.', facts: ['Correct the image perspective or use views with minimal lens distortion before taking proportional measurements.', 'Choose a known dimension such as seat height, hardware size, or a standard object, then test every derived dimension for ergonomic and structural plausibility.', 'Draw front, side, and plan views; a single photograph cannot reveal thickness, back construction, drawer clearance, or the complete load path.', 'Prototype critical angles and posture at full size before committing expensive stock.'] },
  { test: /first five joints|joinery decision chart|splined miters|knock-down joinery/i, answer: 'Choose joinery from the load direction, grain orientation, available long-grain bonding area, required appearance, and whether the project must be disassembled—not from a universal ranking of “strongest” joints.', facts: ['A joint that resists racking needs shoulders, mechanical geometry, or a structural back; glue area alone does not describe the complete load path.', 'Miters hide end grain but benefit from splines, keys, or another reinforcement when the joint carries repeated stress.', 'Knock-down fittings need manufacturer clearances, enough surrounding material, service access, and a way to prevent unnoticed loosening.', 'Cut and load a matching-scrap sample before choosing a smaller joint simply because it is easier to hide.'] },
  { test: /card scraper|western vs\. japanese saws|spokeshave|rasps, files|drawknife/i, answer: 'Choose an edged hand tool by the cut it can control: grain direction, access, curvature, desired surface, workholding, and sharpening method matter more than the tradition or label on the tool.', facts: ['A card scraper needs a prepared square edge and a small consistent hook; excessive pressure and flex create heat without improving the surface.', 'Pull saws and push saws can both work accurately when tooth geometry, plate stiffness, kerf, and workholding suit the cut.', 'Spokeshaves follow curves best with light cuts and grain-aware direction changes; sole shape determines access to concave or convex work.', 'Rasps remove controlled small bites, files refine, and replaceable-blade shaping tools remove stock quickly but may leave a surface needing further refinement.'] },
  { test: /thin-kerf|full-kerf|rip blade vs|saw blade selection/i, answer: 'Choose a saw blade by cut direction, material, machine power, plate stiffness, tooth geometry, and compatibility with the riving knife or brake system; tooth count by itself does not define the result.', facts: ['Ripping blades favor chip clearance along the grain; crosscut blades use more teeth to sever fibers cleanly; combination blades trade peak performance for fewer blade changes.', 'Thin kerf reduces waste and power demand but the plate is more sensitive to deflection, heat, feed pressure, and a mismatched riving knife.', 'Full kerf adds stiffness and material removal and requires adequate motor power and compatible safety components.', 'Clean and inspect the plate, carbide, arbor hole, and runout before blaming tooth count for burning or a wandering cut.'] },
  { test: /cut bevels|rip narrow strips|when you should not use a table saw/i, answer: 'Change the table-saw setup when the stock, offcut, fence, blade tilt, or hand path cannot remain controlled through the whole cut; a jig or different tool is safer than improvising around a trapped part.', facts: ['For a bevel, place the fence and work so the offcut cannot be trapped beneath a tilted blade and verify the guard and riving-knife configuration.', 'For repeated narrow strips, reference the keeper piece safely and use a purpose-built jig or stop arrangement that does not pinch the strip between blade and fence.', 'Do not cut warped stock against an unreliable reference or a part too small to support; use a carrier, sled, bandsaw, track saw, or hand tool route.', 'Plan where the push device, workpiece, and offcut finish before starting, and stop when any path crosses the blade or expected kickback line.'] },
  { test: /track-saw rail lengths|pattern-route|flush-trim edge banding/i, answer: 'A guide or template works only when its full reference remains supported through the cut; size rails and templates for the actual work, stage depth, and prevent the cutter from reaching clamps or unsupported edges.', facts: ['A connected track must be aligned across both joints and long enough to support the saw before entry and after exit.', 'Pattern routing requires a secure template, enough bearing contact, conservative depth, and a feed direction that does not pull the work from control.', 'Flush trimming veneer or banding is safer in shallow, supported cuts; grain reversal can turn a perfectly aligned bearing into a chipped edge.', 'Test the exact cutter, guide, and stock thickness on matching scrap before using the finished part as the experiment.'] },
  { test: /helical vs\. straight-knife cutterheads/i, answer: 'Straight knives offer lower purchase cost and a continuous cutting edge, while segmented or helical-style heads trade higher cost for indexed inserts, localized damage repair, and often lower perceived noise and tear-out.', facts: ['Insert geometry, shear angle, head diameter, bearing load, chip size, and replacement access vary; “helical” is not one universal design.', 'Straight knives require correct height and parallel setup across the head, and one nick can mark the full board width.', 'Indexed inserts must seat on perfectly clean pockets and be tightened in the specified pattern and torque.', 'Price the head, installation, bearings or service, a complete spare edge set, and the surface quality on the species actually milled.'] },
  { test: /leg vise|face vise|quick-release vise|moxon vise|planing stop|doe’s foot/i, answer: 'Choose workholding from the direction and size of force: a vise, stop, holdfast, doe’s foot, or clamp should restrain the work without distorting it or placing hardware in a cutter path.', facts: ['A leg vise supplies deep vertical capacity but needs an anti-racking or parallel mechanism.', 'A face vise is broadly useful; screw placement, jaw width, rack resistance, and bench clearance determine its practical range.', 'Stops and doe’s feet resist planing force without crushing the work, but need a reliable hold-down and a bench that will not rack.', 'Mark dog holes, screw paths, and vise hardware at full scale before drilling the bench.'] },
  { test: /shop-made jigs that save/i, answer: 'Keep a jig only when it removes a repeated setup, improves control, or creates a result that can be verified; label its cutter path and retire it when wear changes the reference.', facts: ['Build a jig around one operation and one known reference rather than adding adjustments that cannot be calibrated.', 'Hardware, knobs, tracks, runners, and clamps must clear every cutter position and stock size.', 'The first accepted scrap part is the calibration standard; keep it until the batch or project is complete.', 'Store the jig with its limits, cutter, setup block, and date marked where the next user will see them.'] },
  { test: /label and inventory your shop/i, answer: 'Inventory only what changes a decision: give frequently used tools a visible home, label consumables by type and size, and set a reorder point for items whose absence stops work.', facts: ['Use names a future user can understand instead of personal abbreviations.', 'Place labels where they remain visible when a drawer, bin, or rack is loaded.', 'Track blades, bits, filters, abrasives, glue dates, finish dates, and critical hardware before counting low-value offcuts individually.', 'Review one zone after a project and remove records that do not help retrieval, maintenance, or purchasing.'] },
  { test: /mobile-base buying guide/i, answer: 'Choose a mobile base from the machine’s loaded weight, footprint, center of gravity, operating forces, floor, wheel placement, and locking method; mobility is useful only when the machine becomes stable before use.', facts: ['Rate the complete machine, extension tables, stand, stored accessories, and stock—not the bare catalog weight.', 'Keep wheels and outriggers from creating a trip or stock-support conflict around the operator position.', 'A universal frame can be economical but must fit the machine’s support points; a dedicated base usually controls footprint and hardware better.', 'Leveling casters should transfer the working load to stable feet and be inspected after each move.'] },
  { test: /HEPA filters for woodworking/i, answer: 'A HEPA label is meaningful only as part of a sealed, compatible system: verify the filter rating, machine approval, gasket fit, dust path, pre-separation, and the method used to contain dust during cleaning and disposal.', facts: ['A high-efficiency filter cannot capture dust that leaks around its gasket, housing, hose, or collection bag.', 'A retrofit filter may overload or damage a vacuum if the manufacturer does not approve its airflow and cleaning behavior.', 'Ambient filtration reduces suspended residue after source capture; it does not replace collection at the cutter or respiratory protection for remaining exposure.', 'Inspect filters by the maker’s method and replace damaged, wet, or uncleanable elements without blowing captured dust back into the shop.'] },
  { test: /push-block|push-stick|machine safety checklist|emergency plan|first-aid station/i, answer: 'A safety system must control the work before the cut and the response after something goes wrong: use guards, distance, workholding, a rehearsed stop path, clear exits, and emergency information matched to the shop.', facts: ['A push device should keep hands farther from the cutter while maintaining downward and forward control without steering the stock into the blade.', 'Inspect stock, cutter, guard, fence or guide, offcut support, power switch, cord, extraction, and body position before starting.', 'Keep emergency contacts, location information, first-aid supplies, extinguisher access, and the main disconnect visible and unobstructed.', 'Do not work alone on an operation whose foreseeable emergency cannot be managed safely from the shop.'] },
  { test: /light a workshop|task light/i, answer: 'Workshop lighting should reveal the line, cutter, surface, and shadowed side without glare or strobing: combine broad ambient light with guarded task lighting positioned outside the material and hand path.', facts: ['Place task lights so the operator’s head and hands do not cast the critical line into shadow.', 'Avoid glare reflected from polished tables and finishes; a high color-rendering source helps reveal surface and color differences.', 'Secure cords, magnets, and articulated arms so vibration cannot move the fixture into a cutter or workpiece.', 'Use listed fixtures and keep required clearance from dust, heat, moving parts, and finishing vapors.'] },
  { test: /workshop electrical planning/i, answer: 'Plan shop electrical service from simultaneous loads, motor starting current, voltage, grounding, dust equipment, heating or cooling, lighting, and future machines; use a licensed electrician and current local code for circuit and installation decisions.', facts: ['Record each machine nameplate and manual requirement instead of estimating from horsepower labels.', 'Separate lighting from machine circuits when practical so a tripped tool does not leave a spinning operation in darkness.', 'Permanent wiring, receptacle type, conductor size, overcurrent protection, and any hazardous-location question require current code and qualified design.', 'Extension cords are temporary; a recurring cord run is evidence that the receptacle layout needs correction.'] },
  { test: /epoxy basics/i, answer: 'Epoxy succeeds when the exact resin and hardener are measured and mixed completely, the wood is clean and stable, the pour stays within the product’s mass and temperature limits, and the full cure is respected.', facts: ['Mixing ratio may be by volume or weight and is product-specific; adding extra hardener does not speed a correct cure.', 'Large or deep masses can overheat, foam, crack, discolor, or create a fire hazard; use the maker’s pour-depth and batch limits.', 'Remove loose bark, oil, dust, and weak fibers, then seal or stage a test when bubbles and absorption are likely.', 'Uncured epoxy can sensitize skin; use the ventilation, gloves, eye protection, cleanup, and disposal method stated by the manufacturer.'] },
  { test: /HVLP turbine vs\. compressor spray/i, answer: 'Choose a turbine when a self-contained finishing system and predictable air source matter; choose a compressor-fed gun when clean dry air of adequate volume already exists and the broader air system justifies its upkeep.', facts: ['Needle, nozzle, air-cap, coating viscosity, fan pattern, and transfer technique must suit the exact product.', 'A turbine adds heat and uses a long hose; stage count, noise, filters, and current nozzle support affect the finish and ownership cost.', 'A compressor system needs enough continuous air, moisture and oil control, regulator capacity, hose, and safe ventilation.', 'Spray a full schedule on a vertical and horizontal sample before judging atomization or changing several settings at once.'] },
  { test: /install built-in shelves|floating shelves|fireplace mantel|shelf with|shoe shelf/i, answer: 'A shelf succeeds when span, thickness, load, edge stiffness, bracket spacing, and the wall connection are designed together; level appearance is not proof that the load reaches structure.', facts: ['Locate verified framing or masonry and select fasteners and anchors for that substrate and complete loaded assembly.', 'Long shelves need greater thickness, front edging, intermediate supports, or reduced load to control sag.', 'A concealed cleat or steel bracket needs enough engagement and a positive way to prevent the shelf from lifting off.', 'Scribe built-ins to the wall only after the case is square, level, and fixed in its intended position.'] },
  { test: /butterfly key|repair stripped screw holes|stabilize a checked|repair a split|patch plywood veneer|fix a wobbly/i, answer: 'A repair should restore the load path and preserve evidence: unload the piece, find the first failed surface or fastener, correct fit and moisture causes, and make the least destructive sound repair.', facts: ['A butterfly key can limit movement across a stable crack but does not make active movement, decay, or a structural split harmless.', 'A stripped hole needs sound surrounding fibers and a fastener suited to the load; stuffing debris into a damaged hole is not a structural repair.', 'Open a joint only as far as needed to clean and refit it; forcing glue into a loose assembly can preserve the movement that caused failure.', 'Keep repaired furniture out of service until adhesive and finish reach full cure, then load it progressively and inspect again.'] },
  { test: /(?!.*(?:box-joint|drawer box|planter box))build (?:a )?.*\bbox\b|\bcrate\b|jewelry box|watch box|keepsake box|vinyl record crate/i, answer: 'A box begins with matching opposite parts, a bottom that does not force the case out of square, and a lid or opening fitted only after the body is stable.', facts: ['Mill opposite sides together and cut each pair from one stop.', 'Dry-clamp and compare diagonals before glue; correct mismatched lengths instead of pulling harder with clamps.', 'Captured solid-wood bottoms need movement clearance, while plywood bottoms can lock the case square when fitted correctly.', 'Fit sliding lids, trays, handholds, and dividers to the assembled opening and leave finish clearance.'] },
  { test: /console|speaker stand|floating TV|record console/i, answer: 'Media furniture needs a square, racking-resistant case, stable equipment support, ventilation, cable access, and wall restraint when its height or mounting makes tip-over possible.', facts: ['Measure the actual equipment, plugs, cable bends, ventilation clearances, and door travel before fixing shelf locations.', 'A structural back or stretchers keep a long low case square; sliding doors still need removal and adjustment access.', 'Speaker stands need a wide stable base, a top sized to the speaker, and a controlled plan for ballast and cable routing.', 'Floating cases require rated brackets or cleats attached to verified structure for the complete loaded weight.'] },
  { test: /picture frame|display frame|phone speaker|ornaments|scrap-wood gifts|building blocks/i, answer: 'Small projects demand full-size layout, safe carriers for short parts, shared stops for repeats, eased handling edges, and hardware or finish tested before the visible blank is cut.', facts: ['Keep hands away from machine cutters by leaving parts oversized, using a carrier, or changing to a hand-tool method.', 'Make repeated frame sides, blocks, or ornaments from one setup and preserve grain and face orientation labels.', 'Test recesses, splines, charging slots, movement hardware, and hanging points in a setup blank first.', 'Round child-contact edges consistently and allow the selected finish to cure fully before handling or use.'] },
  { test: /wooden mallet from firewood/i, answer: 'A wooden mallet needs sound dry stock, continuous straight grain through the handle, a head heavy enough for controlled striking, and a wedged or tapered handle joint that can be inspected and renewed.', facts: ['Split or rive found stock when possible so grain direction remains visible; reject checks, decay, bark pockets, and embedded debris.', 'Orient the handle so runout does not cross the narrow dimension near the head.', 'Fit the mortise and tapered handle in scrap or leave fitting allowance; the head should seat without crushing fibers.', 'Use a light non-slippery finish on the handle and inspect the head, wedge, and end grain before each period of heavy use.'] },
  { test: /zero-clearance inserts/i, answer: 'A zero-clearance insert is a machine-specific, replaceable throat plate fitted level and retained like the original, then kerfed only with a controlled setup that preserves the guard and riving-knife configuration allowed for the cut.', facts: ['Match the factory plate thickness, leveling points, retention tab, arbor clearance, and full blade-tilt path before raising a blade into a blank.', 'Use a sound factory plate or a verified carrier during the initial kerf operation when the machine instructions permit it.', 'Label the blade, kerf, bevel, and dado use on each insert and retire one that warps, cracks, or loses secure support.', 'The insert reduces edge breakout and small-offcut openings but does not replace a guard, riving knife, push device, or safe minimum stock size.'] },
  { test: /laptop stand/i, answer: 'A laptop stand should support the actual computer and typing posture, preserve cooling intake and exhaust, lock every angle positively, and keep cables and fingers clear of the adjustment mechanism.', facts: ['Mock up screen height and keyboard use before choosing the platform angle; an external keyboard changes the ergonomic target.', 'Support the device at broad non-slip points without blocking vents or creating a narrow tipping line.', 'Use captured pivots and positive stops instead of friction alone where collapse could damage the device or hands.', 'Round every touch edge and test the stand through its full travel with the actual laptop and cable connected.'] },
  { test: /bathroom vanity/i, answer: 'A bathroom vanity needs a square, anchored case, sealed vulnerable edges, plumbing access, a countertop and sink supported as their makers require, and clearances checked in the actual room before doors and drawers are fitted.', facts: ['Use moisture-tolerant materials and protect panel edges, cutouts, feet, and splash zones without sealing active leaks inside the case.', 'Map supply, drain, trap, shutoff, outlet, and drawer paths before cutting the back or partitions.', 'Anchor the cabinet to verified structure and support the top and sink from current installation instructions.', 'Finish doors and drawers only after the installed case is level and the final openings are measured.'] },
  { test: /pollinator hotel/i, answer: 'A pollinator hotel should use dry untreated nesting material in replaceable, cleanable modules under a weather-shedding roof; small maintained habitat is safer than a permanent bundle that accumulates moisture, parasites, and debris.', facts: ['Use smooth, closed-end tunnels sized and arranged from current guidance for local solitary bees rather than random splintered holes.', 'Mount the shelter firmly with an open flight path and exposure appropriate to the target insects and regional climate.', 'Keep nesting blocks and tubes removable so occupied material can be protected and old material replaced on a planned schedule.', 'Avoid plastic tubes, exposed sharp edges, mold-prone packed material, and a design too deep to keep dry.'] },
  { test: /hard maple vs\. soft maple/i, answer: 'Hard and soft maple are commercial species groups, not a promise about one board: identify the species when possible, then choose from color, density, machining, figure, availability, and the wear demanded by the project.', facts: ['Hard maple is commonly denser and more abrasion-resistant, while soft-maple species vary and can machine more easily at lower cost.', 'Both groups can burn or tear when cutters are dull or feed stalls; test sharp cutters and grain direction on the actual board.', 'Color, mineral streaks, curl, and heartwood vary within both groups and often matter more visually than the group name.', 'Maple can color unevenly; build the complete dye, stain, or clear-finish schedule on a same-board sample before committing the project.'] },
  { test: /woodworking plans memberships/i, answer: 'Judge a plans membership by complete sample projects, coherent dimensions and cut lists, author and revision transparency, correction support, search quality, licensing, access terms, and whether its library fits projects the shop can actually build.', facts: ['Open a full sample and reconcile every drawing, cut-list line, hardware callout, unit, and step before subscribing.', 'Check whether plans can be downloaded, whether access ends with cancellation, and whether revisions reach saved files.', 'A searchable smaller library with consistent drafting and visible corrections is more useful than a larger undifferentiated catalog.', 'Treat merchant links and plan-count claims as marketing until sample material demonstrates the actual editorial standard.'] },
  { test: /circular saw basics.*without a table saw/i, answer: 'A circular saw can make straight square work when the sheet or board is supported on both sides of the cut, blade depth is set deliberately, and the shoe follows a measured guide without steering by eye.', facts: ['Support sheet goods on rigid foam or a sacrificial grid so neither side falls into and pinches the blade.', 'Measure the actual blade-to-shoe offset and place a straightedge from the finished line.', 'Check base-to-blade square on scrap and verify which face remains clean with the installed blade.', 'Keep the cord, body, and guide clamps clear through the exit and allow the blade to stop before setting the saw down.'] },
  { test: /saw straight by hand.*practice drill/i, answer: 'Sawing straight by hand improves when the work is secure, the line is visible on two faces, the kerf starts with light strokes, and correction happens early instead of twisting the plate after it is buried.', facts: ['Begin at the far corner with the tooth line barely touching the waste side, then lower the saw as the kerf establishes direction.', 'Watch the line on the top and near face and use the reflection in a polished plate only as a secondary cue.', 'Let sharp teeth cut; squeezing the handle or forcing feed bows the plate and drives the kerf away from the line.', 'Use five labeled cuts to compare stance, grip, starting angle, and line control one variable at a time.'] },
  { test: /brace and bit/i, answer: 'A brace gives slow, high-torque drilling control when the lead screw, cutting lips, spur, backing, and workholding match the hole; clear chips before they split the exit or jam the bit.', facts: ['Seat the lead screw on an awl mark and keep the pad centered over the bit axis.', 'Back the exit or stop when the lead screw appears, then finish from the opposite face for a clean through-hole.', 'Withdraw periodically in deep work to clear chips without levering the bit sideways.', 'Inspect the tang, chuck jaws, lead screw, spurs, and cutting lips before increasing force.'] },
  { test: /waterstones vs\. diamond plates vs\. sandpaper sharpening/i, answer: 'Waterstones cut quickly but need flattening, diamond plates retain a flat reference at higher entry cost, and abrasive film on glass or stone lowers the initial cost while making the abrasive a recurring consumable.', facts: ['A sharpening system needs one coarse repair step, one reliable honing step, and a repeatable way to register the bevel.', 'Flattening frequency and the flatness standard matter more than the name of the abrasive.', 'Use lubricant and cleanup appropriate to the abrasive and protect water-sensitive tools and benches.', 'Compare cost over replacement sheets, plate or stone wear, flattening equipment, speed, mess, and the tool steels actually owned.'] },
  { test: /red oak vs\. white oak/i, answer: 'Red and white oak are distinct groups: white oak commonly offers tyloses and better decay resistance, while red oak remains open-pored and should not be substituted outdoors simply because the color and grain look similar.', facts: ['Verify species from reliable stock identification; color alone is not enough.', 'Open red-oak pores can pass air or liquid through end grain, while white-oak tyloses often block the vessels.', 'Both groups move, split near fasteners, and vary in density and machining; use sharp cutters and predrill where required.', 'For exterior work, species durability is only one part of water shedding, compatible hardware, finish, maintenance, and ground-contact design.'] },
  { test: /birdhouse with species-appropriate/i, answer: 'Choose the target bird before cutting the entrance, then use current species guidance for floor size, hole diameter and height, drainage, ventilation, predator protection, habitat, and mounting.', facts: ['A decorative perch can help predators and is unnecessary for cavity-nesting birds.', 'Use untreated stock with a rough interior below the opening and keep the interior unfinished.', 'Provide drainage and a cleanout panel that can be secured against predators.', 'Install the box in habitat and at spacing suited to the target species rather than choosing placement only for human viewing.'] },
  { test: /bat house using conservation/i, answer: 'A bat house should follow current regional conservation guidance for chamber size, rough gripping surfaces, color, solar exposure, mounting height, and open flight path; it supplements rather than replaces natural habitat.', facts: ['Use tall narrow chambers with roughened untreated roost surfaces and no plastic mesh that can trap bats.', 'Seal exterior seams and use a rain-shedding roof while preserving ventilation specified by the selected design.', 'Mount on a building or sturdy pole when current guidance favors it, with clear space below the entrance.', 'Monitor temperature, condition, and occupancy and relocate or modify a consistently unsuitable house rather than assuming any placement will work.'] },
  { test: /CNC|carve|flat-pack/i, answer: 'A CNC job is only as accurate as its stock setup, zero reference, toolpath, workholding, and verified cutter geometry.', facts: ['Confirm actual bit diameter and stick-out before calculating a toolpath.', 'Keep clamps and screws outside every toolpath, including lead-ins, ramps, and rapid moves.', 'Run an air cut above the stock after changing workholding or coordinate assumptions.', 'Tabs, onion-skin passes, and spoilboard surfacing solve different part-holding problems; choose deliberately.'] },
  { test: /finishing-supply cabinet/i, answer: 'Finishing storage begins with each product label and local fire requirements: separate incompatible materials, keep containers closed, control ignition sources, and use only cabinets and waste containers approved for the actual liquids and contaminated rags.', facts: ['A wooden shop cabinet is not a substitute for a listed flammable-liquid cabinet where one is required.', 'Keep safety data, labels, and disposal instructions legible and remove leaking, unknown, or expired material through the approved local route.', 'Drying-oil rags can self-heat; use the exact product and fire-authority storage or disposal method and an approved closed metal waste can where required.', 'Preserve ventilation, spill containment, extinguisher access, and an unobstructed exit instead of filling every available shelf.'] },
  { test: /butcher-block countertop/i, answer: 'A butcher-block countertop needs a dry stable long-grain lamination, movement-friendly cabinet attachment, protected sink and end-grain cutouts, a finish selected for the actual food and water exposure, and a realistic maintenance plan.', facts: ['Use slotted holes or suitable clips across the width so the top can move without splitting or bowing the cabinets.', 'Seal all faces and especially sink, faucet, dishwasher, and end-grain cutouts while preserving service access.', 'Support overhangs, appliance spans, and seams according to the top and cabinet requirements.', 'Make a same-stock finish sample, allow full cure, and give the owner cleaning and refresh instructions.'] },
  { test: /hose hanger/i, answer: 'A hose hanger needs a broad smooth support that does not kink the hose, a drainage and drying path, and fasteners connected to verified wall structure for the full wet-hose load.', facts: ['Measure the hose coil diameter and bend radius instead of copying a small decorative arc.', 'Slope or drain the hidden shelf and keep end grain from trapping water against the wall.', 'Use exterior-compatible hardware and maintain access to inspect wall fasteners.', 'Mount the hanger where the hose can be returned without crossing a walkway or pulling sideways on the support.'] },
  { test: /choose straight boards at the home center/i, answer: 'Choose boards by sighting both faces and edges, comparing twist on a flat reference, checking end grain and moisture differences, and placing knots, checks, crook, bow, and cup against the actual cut list.', facts: ['Sight from one end along each edge and face; rotate the board because one viewing angle can hide crook or twist.', 'Place the board on a known-flat cart or rack and press opposite corners to reveal rocking from twist.', 'Reject defects that cross a critical leg, rail, joint, or visible face instead of assuming every board can be milled straight.', 'Buy enough extra length and width to cut around end checks, knots, damaged edges, and the home center’s storage distortion.'] },
  { test: /dividing a board into equal parts|find center on any board/i, answer: 'Use geometric transfer instead of awkward arithmetic: angle a rule until a convenient multiple spans the width, mark equal divisions, or cross diagonals and transfer from matching edges to find center.', facts: ['Keep both ends of an angled rule on the same reference edges and mark the desired equal increments along the convenient scale.', 'For a rectangle, diagonal intersections locate the geometric center; for irregular stock, define which usable edges control the work first.', 'A center-finding rule or marking gauge is only accurate when both reference edges are straight and the tool is held consistently.', 'Verify the layout by measuring the two outside remnants or folding a paper or story-stick test before drilling or cutting.'] },
  { test: /edge-join boards for a flat panel/i, answer: 'A flat panel starts with stable boards, mating edges that close without force, consistent reference-face orientation, and clamp pressure directed through the panel rather than used to bend bad edges together.', facts: ['Arrange grain and color before jointing, mark cabinetmaker’s triangles, and keep each mating pair together.', 'Joint or plane edges straight enough to close under light hand pressure; a tiny controlled spring joint is optional, not a repair for twist.', 'Use cauls or alternating clamps only as needed to keep faces aligned and recheck the panel as pressure increases.', 'After cure, let the panel equalize before final flattening and attach it so seasonal movement remains possible.'] },
  { test: /upcut vs\. downcut vs\. compression spiral bits/i, answer: 'Use upcut geometry for chip evacuation and a clean lower face, downcut geometry for a cleaner top face and downward force, and compression geometry only when cut depth engages both flute directions to protect both faces.', facts: ['A downcut packs chips into a deep groove and needs conservative depth and effective extraction.', 'An upcut can lift thin or weakly held stock, making workholding and pass depth part of the selection.', 'A compression bit’s upcut length must be buried below the top veneer; a shallow pass can expose the wrong flute and worsen tear-out.', 'Confirm shank, diameter, flute length, maximum speed, feed, and machine or collet compatibility for the exact cutter.'] },
  { test: /sofa arm tray/i, answer: 'A sofa-arm tray should be fitted to a full-size template of the actual arm, wide enough to resist tipping, relieved for upholstery compression, and joined so the two side legs cannot spread under an off-center load.', facts: ['Measure arm width at several points and include a soft non-marking liner or deliberate clearance rather than clamping upholstery tightly.', 'Keep cup or device recesses shallow enough that the remaining top carries the expected load.', 'Reinforce miters or use housed joints because end-grain glue alone does not resist repeated spreading.', 'Test the finished tray with a progressive off-center load and confirm it can be removed without snagging fabric.'] },
  { test: /fix twist in a board/i, answer: 'Remove twist by establishing one stable reference face with a jointer, hand planes, or a securely shimmed planer or router sled, then make the opposite face parallel; a thickness planer alone will copy an unsupported twist.', facts: ['Use winding sticks to locate the high diagonal corners and mark the reference face before removing material.', 'Shim the board so it cannot rock when using a sled; hot glue or stops restrain the shims, not the cutter path.', 'Remove the minimum needed to create a continuous reference and reassess whether enough thickness remains for the part.', 'Severe or returning twist can indicate unstable stock; choose a smaller part or different board instead of forcing a marginal piece into service.'] },
  { test: /drawer box with locking rabbets/i, answer: 'Size a drawer box from the measured opening and exact slide clearance, then cut all locking rabbets from one setup, keep the box square through the bottom installation, and fit the applied front only after travel is correct.', facts: ['Use the smaller front and rear opening measurement when calculating drawer width.', 'Make a complete corner sample in the actual side thickness before cutting the four drawer parts.', 'Compare box diagonals before the bottom or clamps lock the shape.', 'Install slides from matching spacers and use the hardware maker’s setback, notch, and screw locations.'] },
  { test: /planter box/i, answer: 'A planter lasts when soil and irrigation water can drain, vulnerable wood is separated from constant moisture, the liner is removable, and fasteners and finish are compatible with the stock and intended plants.', facts: ['Provide drainage through the liner and wood base instead of creating a sealed basin.', 'Keep untreated vulnerable wood out of soil contact and raise feet above standing water.', 'Use corrosion-resistant fasteners compatible with cedar or treated stock and preserve access to replace the liner.', 'Finish exterior faces only when appropriate and avoid trapping water between a nonbreathing liner and sealed wood.'] },
  { test: /course|education|class|guild|learning path|plan subscription/i, answer: 'Choose education by the project sequence, quality of feedback, instructor transparency, and fit with the tools and time you actually have—not by the size of the video library.', facts: ['Preview a complete lesson and its project files before paying; polished trailers do not show whether dimensions and decisions are explained.', 'Feedback on work, a coherent project sequence, and current safety instruction usually matter more than a very large archive.', 'Check whether access expires, downloads are included, materials assume unavailable machines, and cancellation is straightforward.', 'A useful course names the learner level, prerequisites, finished outcome, and the evidence behind product or technique claims.'] },
  { test: /hearing protection|earmuffs|earplugs|noise/i, answer: 'Reduce noise at the source first, then choose hearing protection that provides enough real-world attenuation, fits correctly, works with other protective equipment, and can be worn for the entire exposure.', facts: ['NIOSH recommends individual quantitative fit testing when available because the package Noise Reduction Rating does not show the protection achieved by a particular wearer.', 'Aim for enough protection to reduce exposure into an appropriate range without overprotecting so heavily that warnings and communication disappear.', 'Earmuffs are usually quick to fit; plugs can work well but depend more heavily on insertion technique and clean handling.', 'Active-noise-canceling headphones are not hearing protection unless they are labeled with an appropriate hearing-protection rating.'] },
  { test: /respirator|respiratory protection/i, answer: 'Select respiratory protection from the identified dust, mist, vapor, or gas hazard; a good face seal and the correct NIOSH-approved filter or cartridge matter more than a generic “dust mask” label.', facts: ['Source capture and ventilation come before relying on a respirator alone.', 'A tight-fitting respirator depends on fit; facial hair or an incompatible pair of glasses can break the seal.', 'Particulate filters do not protect against organic vapors, and vapor cartridges do not replace suitable particulate filtration when both hazards are present.', 'Follow the respirator maker’s inspection, seal-check, storage, replacement, and cartridge-change instructions.'] },
  { test: /safety glasses|goggles|face shield|eye protection/i, answer: 'Use impact-rated eye protection with side coverage for flying particles; add sealed goggles for splash or fine-dust conditions and a face shield as a supplement when the face is exposed.', facts: ['A face shield does not replace primary eye protection beneath it.', 'Prescription eyeglasses are not shop eye protection unless they meet the applicable protective rating and coverage requirements.', 'Choose lenses and frames that remain compatible with hearing and respiratory protection without breaking their fit.', 'Replace deeply scratched, cracked, loose, or chemically damaged eye protection.'] },
  { test: /extension cord|power cord/i, answer: 'Choose a listed extension cord whose conductor size, length, jacket, grounding, and current rating meet the tool and environment; voltage drop and heat increase as a cord gets longer or smaller.', facts: ['Use an outdoor-rated jacket outdoors and preserve the equipment grounding path for grounded tools.', 'Uncoil a cord that could retain heat, keep connections dry and out of traffic, and never use a damaged plug, jacket, or strain relief.', 'The tool manual and cord label control allowable gauge and length; a cord is not a permanent substitute for properly installed wiring.', 'A cord without adequate wire size, strain relief, polarization, continuity, or outdoor jacketing can present shock or fire risk.'] },
  { test: /fire extinguisher|oily-rag|oily rag|flammable|combustible/i, answer: 'Control finishing fire risk by removing ignition sources, following each product label, keeping combustible waste out of piles, and storing or disposing of contaminated rags through the approved local method.', facts: ['Drying oils can release heat as they cure; a crumpled pile can retain that heat.', 'Never improvise rag storage: use the product label and local fire rules, and use an approved closed metal waste can where required.', 'Store flammable liquids only in appropriate closed containers and keep access to exits and extinguishers clear.', 'Choose and place extinguishers from the actual hazards and current local fire guidance, then inspect them on the required schedule.'] },
  { test: /MDF|particleboard|composite wood/i, answer: 'Choose MDF, particleboard, or plywood by load, edge durability, fastener behavior, moisture exposure, surface quality, weight, and verified emissions compliance—not price per sheet alone.', facts: ['Measure the actual panel thickness before setting dados or hardware.', 'MDF machines to a uniform edge but is heavy, creates fine dust, and needs appropriate fasteners and edge treatment.', 'Particleboard depends heavily on face quality, edge support, and hardware designed for the panel.', 'In the United States, hardwood plywood, MDF, and particleboard are among the composite products covered by TSCA Title VI formaldehyde requirements; check current labeling.'] },
  { test: /\b(?:jig|sled|fixture|template|bench hook|shooting board|winding sticks|stop block|push stick|push block)\b/i, answer: 'A shop-made jig earns its space when it makes a repeated operation safer or more consistent and can be checked against a known reference before every use.', facts: ['Mark the complete cutter path on the jig and keep every screw, knob, clamp, and insert outside it.', 'Fit runners without side play but loose enough to move through seasonal humidity changes.', 'Make the first test part from scrap and verify it independently before copying the setup.', 'Retire the jig when a slot, fence, runner, stop, or clamp becomes loose enough to change the result.'] },
  { test: /tool budget|first 10 woodworking tools|starter tool|tool kit/i, answer: 'Spend first on measuring, workholding, one controlled cutting method, drilling, and surface preparation; delay specialized machines until a planned project needs their capacity.', facts: ['A sound square, sharp blade, and stable guide improve the work more than extra motor power in an uncontrolled setup.', 'Price blades, bits, abrasives, batteries, clamps, and dust adapters inside the tool budget.', 'Used corded tools can preserve budget when guards, cords, bearings, fences, and adjustments are complete and safe.', 'Choose a battery platform only after checking the next tools and batteries you are realistically likely to buy.'] },
  { test: /sand|abrasive|grit/i, answer: 'Use the coarsest grit that removes the defect, then refine the scratch pattern instead of sanding longer with a grit that is too fine.', facts: ['For raw furniture parts, 80 or 100 grit removes milling marks; 120 and 150 or 180 grit refine the surface for most film finishes.', 'Do not skip more than one grit in a normal sequence: deep 80-grit scratches can survive a jump straight to 180.', 'Vacuum the surface and inspect it in raking light between grits; dust left on the board can disguise cross-grain scratches.', 'Replace an abrasive when it stops cutting, loads with finish, or needs extra pressure. Extra pressure creates heat and uneven scratch depth.'] },
  { test: /table saw|rip cut|riving knife|push stick/i, answer: 'A table-saw cut is controlled by one reference only: use the fence for ripping and the miter gauge or sled for crosscuts, never both when the offcut can be trapped.', facts: ['A 24-tooth ripping blade clears chips efficiently; a 40- or 50-tooth combination blade is a practical general-purpose choice on a 10-inch saw.', 'Keep the riving knife aligned with the blade and use the guard whenever the operation permits it.', 'Set outfeed support slightly below the saw table so it supports stock without steering it upward.', 'Stand out of the likely kickback line and plan where the push stick, workpiece, and offcut will finish before starting.'] },
  { test: /miter saw|crosscut/i, answer: 'Support the complete board, let the blade reach full speed, and keep the work registered against the fence through the entire crosscut.', facts: ['A fine crosscut blade reduces tear-out, but more teeth also cut more slowly and can burn if the feed is forced.', 'For repeated parts, clamp a stop to an auxiliary fence with clearance so a small offcut cannot become trapped.', 'Check square by cutting a wide test board, flipping one half, and bringing the cut edges together; a doubled gap reveals the error.', 'Wait for the blade to stop before raising it from a narrow offcut.'] },
  { test: /circular saw|track saw|saw guide|plywood cutting/i, answer: 'Support the work so neither side drops into the blade, then guide the saw from a measured offset rather than trying to steer by eye.', facts: ['Measure the exact distance from the blade to the shoe edge and use that offset when placing a straightedge guide.', 'With a typical circular saw, the cleanest face is usually down; confirm on scrap because blade geometry and track-saw splinter strips change the result.', 'Set blade depth so the teeth project only slightly below the stock while preserving full tooth engagement.', 'Use rigid foam or a sacrificial grid to support a full sheet close to the cut.'] },
  { test: /band ?saw|resaw/i, answer: 'Bandsaw accuracy depends on a sharp blade, appropriate tension, stable guides, and a feed rate that lets the gullets clear waste.', facts: ['Use a wider blade for straight resawing and a narrower blade for tight curves; never force a curve tighter than the blade can track.', 'Set side guides close to, but not pinching, the blade and keep the thrust bearing just behind it.', 'Leave milling allowance on a resawn face and joint or plane it after the halves rest.', 'Use a push block or carrier when the remaining part would bring fingers near the blade.'] },
  { test: /jigsaw|scroll saw/i, answer: 'Choose the blade for the material and radius, support the show face, and let the teeth cut without pushing the blade sideways.', facts: ['A narrow blade turns a tighter radius; a wider blade tracks straighter.', 'Reduce splintering with a sharp fine-tooth blade, backing board, or zero-clearance insert appropriate to the saw.', 'Relief cuts let waste fall away before a tight curve closes around the blade.', 'Square the base to the blade with a reliable reference before cutting joinery or paired parts.'] },
  { test: /router|routing|dado|rabbet|roundover|profile/i, answer: 'Router work improves when the bit is sharp, the depth is divided into shallow passes, and enough of the base stays supported throughout the cut.', facts: ['Insert the bit fully, then withdraw it slightly before tightening so the shank is not bottomed in the collet.', 'Use the largest compatible shank available—often 1/2 inch on a full-size router—for reduced deflection in demanding cuts.', 'Move a handheld router against normal bit rotation; on a router table, feed the work from right to left in the usual setup.', 'Test the exact bit height and fence position on matching scrap before touching a project part.'] },
  { test: /jointer|jointing|face-joint|edge square to a face/i, answer: 'A jointer creates one flat face and one straight square edge; it does not make the opposite face parallel by itself.', facts: ['Face-joint first, then edge-joint with the flattened face held against the fence.', 'Take light passes and read the grain to reduce tear-out.', 'Stock must meet the machine manual’s minimum length and thickness; short parts need a different method.', 'After jointing one face, use a planer to make the opposite face parallel.'] },
  { test: /planer|thickness|plane thin stock/i, answer: 'A thickness planer makes the top face parallel to the face riding on its bed; twist or cup must be stabilized or removed first.', facts: ['Feed the reference face down and alternate boards when practical to distribute wear across the cutter head.', 'Take light final passes and support long stock without lifting it into the cutter head.', 'A planer sled can stabilize twisted stock when a jointer is unavailable, but the work must be shimmed so it cannot rock.', 'Allow newly milled boards to rest before the last pass when stock movement is likely.'] },
  { test: /drill(?: press|ing)?|\bhole\b|\bdriver\b|pocket hole|brad-point|forstner|twist bits/i, answer: 'Accurate drilling starts with a visible center mark, a bit suited to the hole, and backing that supports the exit fibers.', facts: ['Use an awl or center punch to keep a small bit from wandering.', 'Brad-point bits locate cleanly in wood; twist bits are useful general-purpose cutters; Forstner bits produce controlled flat-bottomed holes.', 'Back the work with scrap to reduce breakout and clamp it before using larger bits.', 'Set a depth stop or tape flag and verify screw length against the actual joint thickness.'] },
  { test: /glue|adhesive|laminat|edge joint/i, answer: 'A glue joint needs clean mating surfaces, an assembly that closes without heroic pressure, and enough clamp time for the exact adhesive and shop conditions.', facts: ['Most ordinary PVA joints need a thin continuous film on the mating surface; a starved joint is weaker than a neat squeeze-out suggests.', 'Dry-fit the complete assembly and stage clamps before applying glue.', 'Check diagonals while the glue is still open and use cauls to distribute pressure across wide panels.', 'Follow the adhesive label for open time, clamp time, temperature, and full cure; do not load the joint early.'] },
  { test: /\b(?:finish|stain|varnish|polyurethane|oil|shellac|lacquer|paint|topcoat)\b/i, answer: 'Finish the sample before the project: use the same wood, sanding sequence, color step, and number of coats, then judge it only after cure.', facts: ['A common furniture sanding stop is 150 or 180 grit, but the finish manufacturer’s instructions take priority.', 'Thin, even coats cure more reliably than one heavy coat and make runs easier to avoid.', 'Temperature, humidity, ventilation, and previous coatings can change open and cure times.', 'Lay oily rags flat to dry outdoors where permitted or store and dispose of them exactly as the product label and local rules require.'] },
  { test: /dust|shop.?vac|cyclone|respirator|air cleaner|dust hose|2½-inch|4-inch dust/i, answer: 'Dust control needs source capture, adequate airflow, a sealed path, and respiratory protection matched to the remaining exposure.', facts: ['A large machine port and a narrow shop-vac hose solve different problems; reducers add resistance and do not create missing airflow.', 'Keep hose runs short and smooth, seal obvious leaks, and avoid sharp bends near the machine.', 'A cyclone protects the filter from chips but does not replace an appropriate filter.', 'Never place a motor in an unventilated sound enclosure; preserve cooling airflow and manufacturer clearances.'] },
  { test: /CNC|carve|flat-pack/i, answer: 'A CNC job is only as accurate as its stock setup, zero reference, toolpath, workholding, and verified cutter geometry.', facts: ['Confirm actual bit diameter and stick-out before calculating a toolpath.', 'Keep clamps and screws outside every toolpath, including lead-ins, ramps, and rapid moves.', 'Run an air cut above the stock after changing workholding or coordinate assumptions.', 'Tabs, onion-skin passes, and spoilboard surfacing solve different part-holding problems; choose deliberately.'] },
  { test: /lathe|woodturning|spindle turning|turn a (?:simple|lidded|wooden|hardwood)|bowl turning/i, answer: 'Lathe work begins with sound stock, secure mounting, a low starting speed, and tool-rest clearance checked by rotating the blank by hand.', facts: ['Stand out of the firing line when first bringing an irregular blank up to speed.', 'Move the tool rest only with the machine stopped and keep it close without touching the work.', 'Inspect firewood and found stock for checks, embedded metal, bark pockets, and decay.', 'A friction-fit lid must be judged after the wood equalizes; thin walls can move noticeably.'] },
  { test: /chisel|plane|hand saw|hand-tool|dovetail|mortise|tenon/i, answer: 'Hand-tool accuracy comes from sharp edges, secure workholding, visible layout lines, and removing waste in controlled increments.', facts: ['Work from the waste side and leave the line until the final fitting pass.', 'Pare with both hands behind the edge and never brace the work against the body.', 'Test the joint in matching scrap before changing a gauge or fence setting.', 'A polished edge cannot compensate for an incorrect bevel, rounded back, or unstable sharpening reference.'] },
  { test: /sharpen|honing|stone|grind/i, answer: 'A repeatable sharpening system matters more than chasing a fashionable angle or abrasive: establish the primary bevel, raise a burr, refine it, then remove it.', facts: ['Flatten waterstones often enough that the tool is not trained to a hollow reference.', 'Use coarse abrasive for repair and finer abrasive for refining; do not spend polishing time on damage that is still visible.', 'Mark the bevel with a felt-tip pen when checking jig registration.', 'Stop and cool the edge during grinding so heat does not damage the steel.'] },
  { test: /clamp|caul|assembly/i, answer: 'Clamps hold accurate parts together; they should not be used to bend a poor joint into temporary alignment.', facts: ['Dry-fit first and arrange clamps so their forces oppose rather than rack the assembly.', 'Alternate clamp positions above and below a panel to reduce bowing.', 'Use cauls to spread pressure and protect finished faces.', 'Recheck diagonals after pressure is applied because the assembly can move as joints close.'] },
  { test: /square|measure|layout|marking|cut list|diagram|woodworking plan/i, answer: 'Choose one reference face and one reference edge, mark every part from them, and verify the setup with a test rather than trusting the scale alone.', facts: ['Check a square by drawing a line, flipping the tool against the same edge, and drawing again; divergence shows twice the error.', 'Measure repeated parts with a stop or story stick instead of reading a tape for every piece.', 'Mark the waste side and include saw kerf when laying out parts from a fixed board length.', 'Compare case diagonals to diagnose square without assuming the floor or bench is flat.'] },
  { test: /board.?foot|lumber|wood species|hardwood|softwood|walnut|pine|cedar|plywood|MDF|maple|oak|poplar/i, answer: 'Buy lumber by the dimensions and defects you actually receive, not by the nominal label or a photograph of the best face.', facts: ['Board feet equal thickness in inches × width in inches × length in feet ÷ 12.', 'A nominal 2×4 commonly measures about 1-1/2 × 3-1/2 inches; measure the actual batch before drawing joinery.', 'Sight along both faces and edges for bow, crook, cup, and twist, then map knots and checks before cutting.', 'Allow waste for defects, grain matching, milling, and test cuts; highly figured or rough stock usually needs more margin.'] },
  { test: /drawer|slide|reveal/i, answer: 'A reliable drawer starts with a square opening, slide clearance taken from the exact hardware instructions, and a box built to the measured opening.', facts: ['Measure the opening at the front and back; use the smaller dimension when setting the box width.', 'Install slides from a spacer or story stick so both sides share the same setback and height.', 'Check the box diagonals before the bottom locks the shape.', 'Fit the applied front only after the drawer moves freely.'] },
  { test: /\b(?:table|desk|bench|workbench|counter|tabletop|desktop)\b/i, answer: 'A useful work surface begins with the required height, clearances, load, and support span—not a stock photo or nominal board size.', facts: ['Allow a solid-wood top to move across its width with figure-eight fasteners, clips, or slotted holes.', 'Place aprons and stretchers to resist racking without stealing knee, clamp, or drawer clearance.', 'Flatten the base contact points before chasing a twist in the top.', 'Move the finished piece through the doorway plan before committing to permanent joinery.'] },
  { test: /cabinet|bookcase|case|shelf|closet|pantry|locker/i, answer: 'Casework depends on square boxes, consistent reference edges, a back or stretcher that prevents racking, and attachment into verified structure.', facts: ['Cut paired sides together and machine shelf or hardware locations from one reference end.', 'A captured back makes squaring easier; compare diagonals before fastening it.', 'Long shelves need thicker stock, a front edging strip, or a center support to control sag.', 'Tall or climbable furniture needs an anti-tip strategy anchored to suitable structure.'] },
  { test: /chair|stool|seat|footrest|kneeler/i, answer: 'Seating needs conservative joinery, comfortable dimensions confirmed with a mockup, and a progressive stability check before use.', facts: ['Typical dining-seat height is around 17 to 18 inches, but the table and intended user should set the final number.', 'Orient parts so short grain does not carry the primary load.', 'Ease touch edges and inspect every leg joint after the adhesive fully cures.', 'Do not rely on screws into end grain as the primary connection for a repeatedly loaded chair.'] },
  { test: /platform bed|storage bed|bed frame|dresser|wardrobe|blanket chest|nightstand/i, answer: 'Bedroom furniture must fit the mattress or stored items, survive the route into the room, and resist racking or tip-over in service.', facts: ['Use the actual mattress and hardware dimensions rather than a nominal size label.', 'Beds benefit from knock-down rail hardware when they must move through stairs or narrow halls.', 'Tall cases and dressers require suitable anti-tip anchoring.', 'Finish and adhesive must cure fully before bedding or clothing traps odor against the surface.'] },
  { test: /outdoor|garden|patio|pergola|planter|bird|bat house|feeder|compost|hose hanger|firewood rack|porch/i, answer: 'Outdoor work lasts when it drains, avoids end-grain water traps, uses compatible corrosion-resistant hardware, and can be refinished without disassembly.', facts: ['Slope horizontal surfaces or leave drainage gaps instead of trapping standing water.', 'Seal or protect end grain and keep untreated wood away from soil contact.', 'Use exterior-rated fasteners compatible with the wood treatment and species.', 'Structural spans, hanging loads, footings, setbacks, and wildlife dimensions require current local or conservation guidance.'] },
  { test: /cutting board|serving board|cheese board|recipe|food/i, answer: 'Kitchen projects need stable grain orientation, easy-to-clean shapes, fully cured finishes, and no inaccessible seams that trap moisture.', facts: ['Avoid routing deep decorative grooves that cannot be cleaned.', 'Ease edges without creating a knife-catching lip on a cutting surface.', 'Use an adhesive and finish whose manufacturer explicitly supports the intended use after full cure.', 'Wash by hand and dry upright; repeated soaking and dishwashers accelerate joint failure.'] },
  { test: /\b(?:toy|child|kids|dollhouse|growth chart|pet|dog|cat)\b/i, answer: 'Projects for children or pets need rounded edges, captured hardware, stable geometry, and materials selected for the actual contact and abuse they will receive.', facts: ['Eliminate small detachable pieces and exposed fastener points where they create a foreseeable hazard.', 'Round touch edges consistently and inspect for splinters after finish cures.', 'Verify wall, window, or climbing supports against the expected dynamic load.', 'Use finish and hardware guidance appropriate to chewing, skin contact, or the user’s age.'] },
  { test: /\b(?:storage|rack|cart|organizer|cabinet|tool wall|charging station)\b/i, answer: 'Shop storage works when the heaviest item has the shortest fall, every load reaches structure, and frequently used tools can return home without moving something else.', facts: ['Anchor tall racks and cabinets into verified framing or masonry with suitable fasteners.', 'Set shelf spacing from the actual tools, batteries, cases, or lumber rather than a generic interval.', 'Keep chargers ventilated and follow their clearance instructions.', 'Casters and leveling feet must be rated for the loaded cart, not the empty cabinet.'] },
]

export function topicFacts(guide) {
  const titleMatches = factRules.filter((rule) => rule.test.test(guide.title))
  const matches = titleMatches.slice(0, 1)
  const subject = lowerSubject(guide)
  const facts = matches.flatMap((rule) => rule.facts)
  for (const offer of guide.naturalOffers.slice(0, 3)) facts.push(`Treat ${offer.toLowerCase()} as a solution only when it removes a measured constraint in ${subject}; check compatibility, required accessories, storage, and recurring consumables first.`)
  facts.push(`For ${subject}, write down the starting condition, the reference that controls the result, and the visible check that tells you the operation is complete.`)
  facts.push(`Use a matching scrap test before an irreversible step in ${subject}, especially when cutter setup, grain direction, color, fit, or hardware clearance can change the outcome.`)
  return { answer: matches[0]?.answer ?? `Approach ${subject} by fixing the controlling reference first, changing one variable at a time, and checking the result before the next irreversible step.`, facts: [...new Set(facts)] }
}

function projectKind(title) {
  if (/birdhouse/i.test(title)) return 'birdhouse'
  if (/bat house/i.test(title)) return 'bat-house'
  if (/pergola/i.test(title)) return 'pergola'
  if (/picture frame|display frame/i.test(title)) return 'frame'
  if (/cutting board|serving board|cheese board/i.test(title)) return 'board'
  if (/box|crate|chest|trunk|watch box|recipe box|valet tray/i.test(title)) return 'box'
  if (/chair|Adirondack|lounge/i.test(title)) return 'chair'
  if (/stool|footrest|kneeler/i.test(title)) return 'stool'
  if (/bed frame|platform bed|storage bed/i.test(title)) return 'bed'
  if (/rack|cart|organizer|station|tool wall|storage|holder|dock/i.test(title) || /\bstand\b/i.test(title)) return 'rack'
  if (/jig|sled|guide|insert|template|winding sticks|bench hook|shooting board|caul|stop block|push-stick|push-block|router table|drill press table|outfeed table|assembly table|sanding table/i.test(title)) return 'jig'
  if (/bench|workbench/i.test(title)) return 'bench'
  if (/table|desk|island/i.test(title)) return 'table'
  if (/cabinet|bookcase|nightstand|dresser|wardrobe|vanity|console|case|pantry|locker/i.test(title)) return 'case'
  if (/shelf|mantel/i.test(title)) return 'shelf'
  if (/sign|clock|growth chart|ornament|block|phone speaker/i.test(title)) return 'small'
  if (/mallet|turn/i.test(title)) return 'turned'
  return 'shop-project'
}

